import base64, json, os, runpy, shutil, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1", HF_HOME="/tmp/e52-hf",
                  OMP_NUM_THREADS="2", VLLM_WORKER_MULTIPROC_METHOD="spawn")
started = time.time()
out = Path("/kaggle/working/e62g-smoke")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e52")
for name, encoded in json.loads('{"datagen/perturb/premise_variants.py": "", "datagen/perturb/transforms.py": "", "data/e62/eligible.parquet": "", "protocols/E62_PROTOCOL.md": "", "scripts/kaggle_cuda_setup.py": "", "scripts/kaggle_process_guard.py": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
import urllib.request
cuda = runpy.run_path(str(root / "scripts/kaggle_cuda_setup.py"))["prepare_cuda_linker"]()
(out / "cuda-link-check.json").write_text(json.dumps(cuda, indent=2))
subprocess.run([sys.executable, "-m", "venv", "--without-pip", "/tmp/e52-env"], check=True)
py = "/tmp/e52-env/bin/python"
subprocess.run([sys.executable, "-m", "pip", "--python", py, "install", "--no-cache-dir", "-q", "vllm==0.20.0",
               "transformers==5.13.0", "huggingface-hub==1.22.0", "pandas==3.0.3", "pyarrow==24.0.0",
               "bitsandbytes>=0.46.1"], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "--python", py, "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
servers = []
for gpu, port, args in [(0, 8001, ['--model', 'Qwen/Qwen3-8B-AWQ', '--reasoning-parser', 'qwen3']), (1, 8002, ['--model', 'deepseek-ai/DeepSeek-R1-Distill-Llama-8B', '--quantization', 'bitsandbytes', '--reasoning-parser', 'deepseek_r1'])]:
    log = open(out / f"server-{gpu}.log", "w")
    servers.append(subprocess.Popen([py, "-m", "vllm.entrypoints.openai.api_server", *args, *['--dtype', 'float16', '--max-model-len', '16384', '--gpu-memory-utilization', '0.90', '--max-num-seqs', '4'],
                                     "--port", str(port)], env={**os.environ, "CUDA_VISIBLE_DEVICES": str(gpu)},
                                    stdout=log, stderr=subprocess.STDOUT))
for (gpu, port, _), server in zip([(0, 8001, ['--model', 'Qwen/Qwen3-8B-AWQ', '--reasoning-parser', 'qwen3']), (1, 8002, ['--model', 'deepseek-ai/DeepSeek-R1-Distill-Llama-8B', '--quantization', 'bitsandbytes', '--reasoning-parser', 'deepseek_r1'])], servers):
    deadline = time.time() + 2400
    while True:
        try:
            if urllib.request.urlopen(f"http://127.0.0.1:{port}/health", timeout=5).status == 200:
                break
        except OSError:
            pass
        if server.poll() is not None or time.time() > deadline:
            raise SystemExit(f"server on GPU {gpu} did not come up; see server-{gpu}.log")
        time.sleep(10)
    print(f"server on GPU {gpu} ready after {time.time() - started:.0f} s", flush=True)
guard = runpy.run_path(str(root / "scripts/kaggle_process_guard.py"))["run_guarded"]
launcher = ("import subprocess, sys\n"
            f"procs = [subprocess.Popen([sys.argv[1], *argv]) for argv in [['datagen/perturb/premise_variants.py', '--pool', 'data/e62/eligible.parquet', '--out-dir', '/kaggle/working/e62g-smoke/w0/e62', '--generator', 'Qwen/Qwen3-8B-AWQ', '--checker', 'deepseek-ai/DeepSeek-R1-Distill-Llama-8B', '--generator-url', 'http://127.0.0.1:8001/v1', '--checker-url', 'http://127.0.0.1:8002/v1', '--checker-temperature', '0.6', '--max-tokens', '12000', '--num-shards', '150', '--shard-index', '0']]]\n"
            "sys.exit(max(p.wait() for p in procs))")
result = guard([py, "-c", launcher, py], root, out / "generate.log", timeout=7200.0)
for server in servers:
    server.terminate()
(out / "execution.json").write_text(json.dumps({**result, "end_to_end_seconds": time.time() - started}, indent=2))
raise SystemExit(result["exit_code"])
